  ('commonWelfare', '[{"title":"병 봉급","desc":"이병 75만 원 · 일병 90만 원 · 상병 120만 원 · 병장 150만 원 (2025년 인상분, 2026년 동결)"},{"title":"장병내일준비적금","desc":"월 최대 55만 원까지 저축하면 정부가 납입 원금의 100%를 매칭지원금으로 더해, 은행 이자(약 5%, 비과세)와 함께 전역할 때 목돈으로 받습니다."},{"title":"휴가·외출","desc":"연가·포상휴가 등 정기 휴가와 평일 외출 제도가 전 군 공통으로 운영됩니다."},{"title":"자기개발 지원","desc":"복무 중 자격증 응시료, 원격강좌, 도서 구입 등 자기개발 비용 일부를 지원합니다."},{"title":"간부 공통","desc":"군인연금(장기 복무 시), 간부 숙소·관사, 군 병원 진료, 자녀 학자금 등 군인 복지가 적용됩니다."}]'::jsonb),
